message.content:
{
  "personality": {
    "traits": ["谨慎", "务实", "寡言"],
    "values": ["信义", "安稳"],
    "flaws": ["过于固执"]
  },
  "voice": {
    "register": "平实，略带官腔",
    "accent": "河畔口音，尾音短促",
    "habits": ["说话前先清嗓子", "常以手抚须"],
    "samples": [
      "这批货的数目，得再点一遍。",
      "河上风大，缆绳要系双结。",
      "行会里的事，照规矩办。"
    ]
  },
  "background": "生在河埠，长在船上，年轻时随商船跑过几趟远水，后来腿脚落了毛病，便留在埠头替行会管些杂事。娶了白生，老来得子，取名阎和。如今每日在码头清点货物、安排泊位，闲时补补旧船具，日子过得紧巴却安稳。",
  "currentConcern": "入秋后水位降得厉害，大船靠不了岸，行会里人心浮动，怕出乱子。",
  "goals": [
    "把阎和拉扯大，教他识些字、懂些规矩。",
    "攒些人情，让白生少操劳。"
  ],
  "fears": ["河上出事，行会散了，一家没了着落。"],
  "knowledge": {
    "unknown": [
      "上游为何突然少雨。",
      "行会账目里那些对不上的数目去了哪里。"
    ]
  },
  "relationships": [
    {
      "with": "npc_pop_bs_005_2",
      "relation": "子女",
      "note": "老来得子，疼在心里，嘴上却严。常带他在埠头认船认缆。"
    },
    {
      "with": "npc_pop_bs_005_3",
      "relation": "伴侣",
      "note": "白生操持家务，他管外头的事，话不多，但事事让着。"
    }
  ],
  "visibleFeature": "左眉有一道旧疤，是早年系缆时被弹起的缆绳所伤；右手小指缺了一节，指节粗大，常年沾着河泥与桐油。"
}
